class Solution {
    int N;
    vector<int> tree;

    void update(int node, int lo, int hi, int pos, int val) {
        if (lo == hi) {
            tree[node] = max(tree[node], val);
            return;
        }
        int mid = (lo + hi) / 2;
        if (pos <= mid) update(2 * node, lo, mid, pos, val);
        else update(2 * node + 1, mid + 1, hi, pos, val);
        tree[node] = max(tree[2 * node], tree[2 * node + 1]);
    }

    int query(int node, int lo, int hi, int l, int r) {
        if (r < lo || hi < l) return 0;
        if (l <= lo && hi <= r) return tree[node];
        int mid = (lo + hi) / 2;
        return max(query(2 * node, lo, mid, l, r),
                   query(2 * node + 1, mid + 1, hi, l, r));
    }

public:
    int lengthOfLIS(vector<int>& nums, int k) {
        N = 100000;
        tree.assign(4 * N + 4, 0);
        int ans = 0;
        for (int x : nums) {
            int l = max(1, x - k);
            int r = x - 1;
            int best = 0;
            if (l <= r) best = query(1, 1, N, l, r);
            update(1, 1, N, x, best + 1);
            ans = max(ans, best + 1);
        }
        return ans;
    }
};
